DROP TABLE IF EXISTS `product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product` (
  `id` varchar(64) NOT NULL,
  `store_id` int NOT NULL,
  `name` varchar(1000) NOT NULL,
  `category_id` int DEFAULT NULL,
  `regular_price` decimal(18,2) DEFAULT NULL,
  `online_price` decimal(18,2) DEFAULT NULL,
  `discount_pct` decimal(10,2) DEFAULT NULL,
  `currency` varchar(5) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `url` varchar(500) DEFAULT NULL,
  `canonical_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_product_store` (`store_id`),
  KEY `fk_product_cat` (`category_id`),
  KEY `fk_product_canonical` (`canonical_id`),
  CONSTRAINT `fk_product_canonical` FOREIGN KEY (`canonical_id`) REFERENCES `canonical_product` (`id`),
  CONSTRAINT `fk_product_cat` FOREIGN KEY (`category_id`) REFERENCES `category` (`id`),
  CONSTRAINT `fk_product_store` FOREIGN KEY (`store_id`) REFERENCES `store` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
