DROP TABLE IF EXISTS `product_match`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product_match` (
  `id` int NOT NULL AUTO_INCREMENT,
  `canonical_id` int NOT NULL,
  `product_id` varchar(50) NOT NULL,
  `store_id` int NOT NULL,
  `similarity_score` float NOT NULL,
  `status` enum('auto_matched','needs_review') NOT NULL DEFAULT 'needs_review',
  `matched_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_match` (`canonical_id`,`product_id`,`store_id`),
  KEY `store_id` (`store_id`),
  CONSTRAINT `product_match_ibfk_1` FOREIGN KEY (`canonical_id`) REFERENCES `canonical_product` (`id`),
  CONSTRAINT `product_match_ibfk_2` FOREIGN KEY (`store_id`) REFERENCES `store` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=27674 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

